n30204.content:
\begin{definition}[\texttt{Ia}]\label{Ia}
	\lean{annuity.Ia}
	\leanok
	\uses{id_mul_geom_sum}
	Present value of an increasing annuity: $\sum_{k=1}^n k v^k$
	where $v=1/(1+i)$.
\end{definition}

n30205.content:
\begin{definition}[\texttt{geom\_sum}]\label{geom_sum}
	\lean{annuity.geom_sum}
	\leanok
	$\mathrm{geom\_sum}$ is the function $g : \mathbb N \to \mathbb R \to \mathbb R$ given by
	$g(n,v)=
	  \sum_{k=1}^n v ^ k$.
\end{definition}

n30206.content:
\begin{definition}[\texttt{bond\_price\_sum}]\label{bond_price_sum}
	\lean{annuity.bond_price_sum}
	\leanok
	\uses{geom_sum}
The bond price sum is
$r \cdot \text{geom\_sum} (n, v) + v ^ n$.
\end{definition}

n30207.content:
\begin{definition}[\texttt{bond\_price}]\label{bond_price}
	\lean{annuity.bond_price}
	\leanok
	\uses{bond_price_sum}
The bond price is the bond price sum with $v=1/(1+i)$.
\end{definition}

n30208.content:
\begin{definition}[\texttt{D}]\label{D}
	\lean{D}
	\leanok
	\uses{Ia, bond_price}
	Macaulay duration:\\
    \verb!(r * Ia n i + n * (1+i)!$^{-n}$\verb!) / bond_price n i r!
\end{definition}

n30209.content:
\begin{lemma}[\texttt{id\_mul\_geom\_sum\_formula}]\label{id_mul_geom_sum_formula}
	\lean{annuity.id_mul_geom_sum_formula}
	\leanok
	\uses{id_mul_geom_sum}
Given $x\in\mathbb R$ with $x \ne 1$ and $n\in \mathbb N$, we have
\[
	\sum_{k=1}^n k \cdot x^k =
	  \frac{x \cdot (n \cdot x ^ {n + 1} - ((n + 1) \cdot x ^ n) + 1)}{(x - 1) ^ 2}.
\]
\end{lemma}

n30210.content:
\begin{proof}
	\leanok
	A well-known formula from undergraduate mathematics.
\end{proof}

n30211.content:
\begin{definition}[\texttt{annuity.a}]\label{a}
	\lean{annuity.a}
	\leanok
	\uses{geom_sum}
	The present value of annuity function $a : \mathbb N \to \mathbb R \to \mathbb R$
	is defined by
	\[
		a_{\overline n|i}=g(n, (1 + i)^{-1})
	\] with $g$ as in Definition \ref{geom_sum}.
\end{definition}

n30212.content:
\begin{definition}[\texttt{annuity.a\_formula}]\label{a_formula}
	\lean{annuity.a_formula}
	\leanok
	The expression for the present value of annuity
	that is well-defined even for non-integer $n$:
	$(1 - (1+i)^{-n}) / i$.
\end{definition}

n30213.content:
\begin{lemma}[\texttt{a\_eq\_a\_formula}]\label{a_eq_a_formula}
	\lean{annuity.a_eq_a_formula}
	\leanok
	\uses{a_formula, a}
	The value of the expression for the present value of annuity
	that is well-defined even for non-integer $n$
	is equal to the original value.
\end{lemma}

n30214.content:
\begin{proof}
	\leanok
	Apply the formula $\sum_{i=0}^{n-1} x^i = \frac{x^n - 1}{x - 1}$ to $x$
	being the discount factor $(1+i)^{-1}$.
\end{proof}

n30215.content:
\begin{definition}[\texttt{CPT\_PV}]\label{CPT_PV}
	\lean{CPT_PV}
	\leanok
	\uses{a}
	Defines a function to compute PV, as\\
	\verb!  - PMT * (annuity.a N (IY / 100)) - FV * (1 + IY/100)!$^{-N}$.
\end{definition}

n30216.content:
\begin{definition}[\texttt{CPT\_PMT}]\label{CPT_PMT}
	\lean{CPT_PMT}
	\leanok
	\uses{a}
	Defines a function to compute PMT, as\\
	\verb!(-PV - FV * (1 + IY / 100)!$^{-N}$\verb!) / annuity.a N (IY / 100)!.
\end{definition}

n30217.content:
\begin{definition}[\texttt{CPT\_IY}]\label{CPT_IY}
	\lean{CPT_IY}
	\leanok
	\uses{a}
	Defines a function to compute IY.
\end{definition}

n30218.content:
\begin{definition}[\texttt{CPT\_N}]\label{CPT_N}
	\lean{CPT_N}
	\leanok
	Defines a function to compute N, as\\
	\verb!  (log ((PV * (IY / 100) + PMT) / (PMT - FV * (IY / 100)))) / (log (1 + IY / 100)!$^{-1}$\verb!)!.
\end{definition}

n30219.content:
\begin{definition}[[\texttt{CPT\_FV}]]\label{CPT_FV}
	\lean{CPT_FV}
	\leanok
	\uses{a}
	Defines a function to compute FV, as\\
	\verb!(- PV - PMT * (annuity.a N (IY / 100))) / ((1 + IY/100)!$^{-N}$\verb!)!.
\end{definition}

n30222.content:
\begin{lemma}[\texttt{IY\_eq\_CPT\_IY}]\label{IY_eq_CPT_IY}
	\lean{IY_eq_CPT_IY}
	\leanok
	\uses{CPT_IY,duration_equation}
	If $\N \ne 0$, $\PMT \ge 0$, $0 \le \PV + \PMT \cdot \N + \FV$, $\PV < 0$, $\FV > 0$, $\IY < -100$, and the annuity equation holds for
  IY, PMT, PV, FV, and N, then $\IY=\CPTIY$.
\end{lemma}

n30223.content:
\begin{proof}
	\leanok
	Use the Intermediate Value Theorem and strict monotonicity
	in the Annuity Equation as a function of interest rate.
\end{proof}

n30224.content:
\begin{lemma}[\texttt{PV\_eq\_CPT\_PV}]\label{PV_eq_CPT_PV}
	\lean{PV_eq_CPT_PV}
	\leanok
	\uses{CPT_PV}
	Assume the annuity equation holds for $\IY, \PMT, \PV, \FV$ and $\N$. Then
	$\PV=\CPTPV$.
\end{lemma}

n30226.content:
\begin{lemma}[\texttt{FV\_eq\_CPT\_FV}]\label{FV_eq_CPT_FV}
	\lean{FV_eq_CPT_FV}
	\leanok
	\uses{CPT_FV}
	Assume the annuity equation holds for $\IY, \PMT, \PV, \FV$ and $\N$, and $\IY \ne -100$. Then
	$\FV=\CPTFV$.
\end{lemma}

n30228.content:
\begin{lemma}[\texttt{N\_eq\_CPT\_N}]\label{N_eq_CPT_N}
	\lean{N_eq_CPT_N}
	\leanok
	\uses{CPT_N,a_eq_a_formula}
	Assume the annuity equation holds for $\IY, \PMT, \PV, \FV$ and $\N$.

	Assume $\IY/100\notin\{-2,-1,0\}$, and
    $\FV \cdot (\IY / 100) - \PMT \ne 0$.
	Then maturity $\N$ equals $\CPTN$.
\end{lemma}

n30230.content:
\begin{theorem}[\texttt{annuity\_equation\_unique\_solvability}]\label{annuity_equation_unique_solvability}
	\lean{annuity_equation_unique_solvability}
	\leanok
	\uses{PMT_eq_CPT_PMT, IY_eq_CPT_IY, PV_eq_CPT_PV, FV_eq_CPT_FV, N_eq_CPT_N}
	Given real numbers $\IY>0$, $\PMT\ge 0$, $\PV<0$, $\FV>0$ and a natural number $\N \ge 1$,
	satisfying the annuity equation, with 
	$(\FV \cdot (\IY / 100) - \PMT \ne 0$, we can compute each of the five variables uniquely from the other four.
\end{theorem}

n30231.content:
\begin{proof}
	\leanok
	We combine the results of Lemmas \ref{PMT_eq_CPT_PMT}, \ref{IY_eq_CPT_IY}, \ref{PV_eq_CPT_PV}, \ref{FV_eq_CPT_FV}, and \ref{N_eq_CPT_N}.
\end{proof}

n30232.content:
\begin{lemma}[\texttt{AriMagic.exists\_pos\_root\_of\_limits}]\label{AriMagic.exists_pos_root_of_limits}
	\lean{AriMagic.exists_pos_root_of_limits}
	\leanok
If a continuous function starts positive at 0 and tends to a negative limit, it has a positive root.
\end{lemma}

n30233.content:
\begin{proof}
	\leanok
	A simple application of the Intermediate Value Theorem, formalized by Aristotle.
\end{proof}

n30234.content:
\begin{definition}[\texttt{duration\_equation}]\label{duration_equation}
	\lean{annuity.duration_equation}
	\leanok
	\uses{bond_price, Ia}
	Defined to equal
   \verb!d * annuity.bond_price n i r! \\
   \verb!- (r * annuity.Ia n i + ↑n * (1 + i)!$^{-n}$\verb!) = 0!.
\end{definition}

n30235.content:
\begin{lemma}[\texttt{AriMagic.unique\_solution\_n}]\label{AriMagic.unique_solution_n}
	\lean{AriMagic.unique_solution_n}
	\leanok
	\uses{AriMagic.exists_pos_root_of_limits}
	Given $D>0, i>0, r>0$, with $D < 1 + 1/i$, there is a unique solution for the maturity $N$
	in the duration equation with duration $D$, yield rate $i$, and coupon rate $r$.
\end{lemma}

n30236.content:
\begin{proof}
	\leanok
	This is a subtle result, outsourced to Aristotle.
\end{proof}

n30237.content:
\begin{theorem}[\texttt{eq\_CPT\_I\_of\_D}]
	\label{eq_CPT_I_of_D}
	\lean{eq_CPT_I_of_D}
	\leanok
	\uses{D}
	If $D>1$, $n \ge 2$, and $r > 0$ then we can uniquely
	compute the yield rate $i > -1$ from the duration equation.
\end{theorem}

n30238.content:
\begin{proof}
\leanok
This proof was outsourced to Aristotle.
\end{proof}

n30239.content:
\begin{theorem}[\texttt{eq\_CPT\_N\_of\_D}]
	\label{eq_CPT_N_of_D}
	\lean{eq_CPT_N_of_D}
	\leanok
	\uses{D,duration_equation,AriMagic.unique_solution_n,id_mul_geom_sum_formula}

Given $n\in\mathbb N$ with $n>1$ and $i,d,r$ positive real numbers, with  $d < 1 + 1 / i$,
 if the duration equation holds for $n,i,r,d$ then $n$ is uniquely determined,
 and given by the Lean function \verb!CPT_N_from_D!.
\end{theorem}

n30240.content:
\begin{proof}
	\leanok
	This result is simply a wrapper for Lemma \ref{AriMagic.unique_solution_n}.
\end{proof}

